const errorData = $input.first().json;

const failedWorkflow = errorData.workflow?.name || 'Unknown Workflow';
const executionId = errorData.execution?.id || 'N/A';
const lastNodeExecuted = errorData.execution?.lastNodeExecuted || 'Unknown Node';
const errorMessage = errorData.execution?.error?.message || 'No error message provided';
const timestamp = new Date().toISOString();

const alertPayload = {
  alertType: 'CRITICAL_WORKFLOW_FAILURE',
  service: 'LendLoop Automations',
  workflow: failedWorkflow,
  executionId,
  failedNode: lastNodeExecuted,
  error: errorMessage,
  timestamp
};

console.error('[LendLoop Automation Alert] Workflow Failure Detected:', JSON.stringify(alertPayload, null, 2));

return [{ json: alertPayload }];

// In production, wire this to Slack, Discord webhook, or PagerDuty
const alert = $input.first().json;
console.log(`[ALERT NOTIFICATION SENT] Alert sent to operations on-call for ${alert.workflow}`);
return [{ json: { status: 'alert_dispatched', alert } }];
